import csv
import json

input_file = '/tmp/ageval/data.csv'
output_file = '/tmp/ageval/data.json'

def convert_value(val):
    try:
        # Check if it's an integer
        if val.isdigit():
            return int(val)
        # Check if it's a float
        f = float(val)
        if f.is_integer():
            return int(f)
        return f
    except ValueError:
        return val

with open(input_file, mode='r', encoding='utf-8') as csvfile:
    reader = csv.DictReader(csvfile)
    data = []
    for row in reader:
        new_row = {}
        for key, value in row.items():
            new_row[key] = convert_value(value)
        data.append(new_row)

with open(output_file, mode='w', encoding='utf-8') as jsonfile:
    json.dump(data, jsonfile, indent=4)

